# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""TLE implementation of the FlagGems ``__ilshift__`` operator.

``torch.Tensor.__ilshift__(self, other)`` computes ``self << other`` and stores
the result back into the caller's ``self`` storage, returning that same tensor
(``flag_gems.ops.__ilshift__`` is ``pointwise_dynamic`` over ``a << b`` with
``out0=self``).  The mutation is observable, so this candidate never allocates
an output: the shift is written straight back into ``self``.

Bulk traffic goes through the TLE DSA path.  A persistent kernel walks the
tensor in fixed byte-sized tiles; each tile is staged GM -> UB with
``tle.dsa.copy``, shifted on the UB tile, and written back with a second
``tle.dsa.copy`` whose source buffer is the staged input buffer itself, so no
third UB allocation is needed.  The loop is staged by ``tle.dsa.pipeline`` so one
tile's DMA overlaps the previous tile's vector work.

The shift is a mask/select/multiply network, not a per-lane ``<<``.  Target
evidence (msprof, round 1): a tensor ``arith.shli`` becomes ``hivm.hir.vshl``,
which the backend emits as a per-lane *scalar* loop -- 99.5% of the AIV scalar
pipe busy, VEC/MTE2/MTE3 all under 0.3%, and 466 ms for a 2**30 int16 case
carrying only 6.4 GB.  A left shift is multiplication by ``2**count``, and
``2**count`` factors over the set bits of the count into a product of
``2**(2**k)``; testing bit ``k`` of the count is one ``and`` with a constant.
``vand``/``vsel``/``vmul`` are all vector instructions, so the network leaves the
scalar pipe idle.  Measured effect (round 2): the 2**30-element bulk cases fell
from 466.16 / 468.70 ms to 18.97 / 22.90 ms (314x / 402x versus the reference),
with the small shapes improving too rather than regressing.

Reference semantics had to be measured, not assumed (debug job on the target:
35 shift counts x 6 magnitude patterns x uint8/int8/int16/int32/int64): this
stack evaluates the shift at 32 bits and then narrows, so the count is taken
modulo 32 and a count of ``w`` or more (``w`` = element bits) yields zero rather
than wrapping into range.  int32/int64 therefore need only the network, while
int16/uint8/int8 also need a kill stage that zeroes elements whose count has any
bit of ``(32 - w)`` set.  Out-of-range counts are the common case here, not an
edge case: the timing harness builds both operands with
``torch.randint(iinfo.min, iinfo.max, ...)``.

Toolchain constraints this file encodes (all confirmed on the target):
  * GM-side addresses in ``tle.dsa.copy`` must be ``ptr + <offset tensor>``; a
    scalar offset fails legalization.
  * ``tle.dsa.copy`` has no mask operand, so the ragged remainder is handled by
    a separate masked ``tl.load``/``tl.store`` kernel.
  * ``tle.dsa.pipeline`` accepts ``num_stages <= 2`` only.
  * ``tle.dsa`` exposes no bitwise ops; the shift is done on the UB tile
    returned by ``tle.dsa.to_tensor``.
"""

import logging

import torch
import torch_npu  # noqa: F401  # must precede triton on this platform

import triton
import triton.experimental.tle as tle
import triton.language as tl

logger = logging.getLogger(__name__)

# Bytes staged per tile, keyed by element size.  The unrolled select network
# keeps every stage's multiply and select result live at once, so its UB working
# set scales with the tile *in elements*, not in bytes:
#   * a 16 KB tile overflows the 1.50 Mbit UB (target preflight: 2228480 bits
#     required) -- measured in round 2 on all five smoke cases;
#   * 8 KB is the largest tile that fits for 2/4/8-byte dtypes and was measured
#     fast there (bulk cases 19-23 ms), but the 1-byte path then gets twice the
#     element count for about the same bits per element and still overflows
#     (1835008 bits at BLOCK=8192, 1769472 bits in the masked tail kernel).
# So the tile is chosen in elements: 4096 elements for the 8-bit dtypes, where
# the measured uint8 footprint extrapolates to ~0.92 Mbit, and 8192 bytes
# elsewhere.  The DMA side has enormous headroom (MTE2/MTE3 sat at 0.3%/0.1%
# when the kernel was scalar-bound), so tile size costs nothing there.
_TILE_BYTES = {1: 4096, 2: 8192, 4: 8192, 8: 8192}
_TILE_BYTES_DEFAULT = 8192

# Depth handed to `tle.dsa.pipeline` (the toolchain caps it at 2).
_NS = 2

# itemsize -> (stages, kill_mask): one stage per bit of the count modulo 32,
# plus a mask of the counts a 32-bit shift sends past the element width (zero
# result) -- `32 - bits` for sub-word dtypes, none for 32/64-bit.
_SHIFT_PLAN = {1: (3, 24), 2: (4, 16), 4: (5, 0), 8: (6, 0)}
_DEFAULT_PLAN = (6, 0)

_NVEC_CACHE = [None]


def _vector_core_count():
    """Vector-core count of the active device, or None if it cannot be read.

    Never hard-code a core count: the development service reports a B4 part
    while the submission target is a B2, so the grid cap must come from a
    runtime query.
    """
    if _NVEC_CACHE[0] is None:
        try:
            from triton.runtime import driver

            props = driver.active.utils.get_device_properties(
                torch.npu.current_device()
            )
            nvec = int(props["num_vectorcore"])
            _NVEC_CACHE[0] = nvec if nvec > 0 else -1
        except Exception:  # noqa: BLE001 - fall back to one tile per program
            _NVEC_CACHE[0] = -1
    return None if _NVEC_CACHE[0] == -1 else _NVEC_CACHE[0]


@triton.jit
def _shift_lanes(ra, rb, STAGES: tl.constexpr, KILL: tl.constexpr):
    """``ra << rb`` for element-wise counts, using vector ops only.

    ``2**rb`` is the product of ``2**(2**k)`` over the set bits of ``rb``, so a
    stage is ``and`` (test one constant bit of the count), ``select``, and a
    multiply by a constant power of two.  Multiplication by a power of two wraps
    exactly like a left shift, and ``KILL`` reproduces the reference's
    "count >= element width means zero" rule, so the result is bit-identical to
    ``ra << rb`` for every count, in range or not.

    Every constant is materialised in the *operand's own* dtype.  Writing the
    literals bare made the frontend promote both the mask compare and the value
    chain to i32, so the captured backend IR for int16 was
    ``andi i16 -> extsi i32 -> cmpi i32 -> muli i32 -> select i32`` with one
    final ``trunci``: half-width data paying full 32-bit vector cost.  Round-3
    profiling measured the consequence -- int16 (4096-element tiles, 4 stages +
    kill) spent *more* VEC time than int32 (2048-element tiles, 5 stages) for
    the same 2**30 element count, 14205.8 us versus 13472.3 us, with the VEC
    pipe at 0.751 of aiv_time and no idle pipe to recover.  Same-dtype constants
    keep the network at the element width; the wrap-around multiply is what the
    reference's 32-bit-then-narrow behaviour reduces to for sub-word types.

    The compare is written in the *equality* sense and the select takes the
    unchanged value first.  Round-4 IR (recompile at
    ``bisheng_device_input_before_optimization``) shows each bit test lowering as
    ``vand i16 -> vcast i16->f16 -> vcmps_eq f16 0 -> vnot i1 -> vmuls_vs i16 ->
    vsel i16``: the ``vnot`` only re-inverts the compare, which the select
    polarity can absorb, so one of the six vector ops per condition is redundant.
    int16 runs four stages plus the kill condition, i.e. five of those chains per
    tile, and round-4 profiling put VEC at 0.585 of ``aiv_time`` with the DMA
    engines only ~33% busy and no idle pipe, so the vector instruction count is
    what the remaining latency tracks.
    """
    res = ra
    zero_b = tl.zeros_like(rb)
    for k in tl.static_range(STAGES):
        bit = tl.full(rb.shape, 1 << k, rb.dtype)
        factor = tl.full(res.shape, 1 << (1 << k), res.dtype)
        res = tl.where((rb & bit) == zero_b, res, res * factor)
    if KILL != 0:
        kill = tl.full(rb.shape, KILL, rb.dtype)
        res = tl.where((rb & kill) == zero_b, res, tl.zeros_like(res))
    return res.to(ra.dtype)


@triton.jit(do_not_specialize=["n_tile"])
def _shift_bulk(
    a_ptr,
    b_ptr,
    n_tile,
    BLOCK: tl.constexpr,
    NS: tl.constexpr,
    STAGES: tl.constexpr,
    KILL: tl.constexpr,
):
    """In-place ``a << b`` over whole tiles; result is stored back into ``a``."""
    pid = tl.program_id(0)
    nprog = tl.num_programs(0)
    cnt = tl.maximum((n_tile - pid + nprog - 1) // nprog, 0)

    a0 = tle.dsa.alloc(
        [BLOCK], dtype=a_ptr.dtype.element_ty, mem_addr_space=tle.dsa.ascend.UB
    )
    b0 = tle.dsa.alloc(
        [BLOCK], dtype=b_ptr.dtype.element_ty, mem_addr_space=tle.dsa.ascend.UB
    )
    lane = tl.arange(0, BLOCK)
    for i in tle.dsa.pipeline(0, cnt, 1, num_stages=NS):
        off = (pid + i * nprog) * BLOCK + lane
        with tle.dsa.hint(inter_no_alias=True):
            tle.dsa.copy(a_ptr + off, a0, [BLOCK])
            tle.dsa.copy(b_ptr + off, b0, [BLOCK])
        ra = tle.dsa.to_tensor(a0, writable=False)
        rb = tle.dsa.to_tensor(b0, writable=False)
        if rb.dtype != ra.dtype:
            rb = rb.to(ra.dtype)
        res = _shift_lanes(ra, rb, STAGES, KILL)
        tle.dsa.copy(
            tle.dsa.to_buffer(res, space=tle.dsa.ascend.UB, bind_buffer=a0),
            a_ptr + off,
            [BLOCK],
        )


@triton.jit(do_not_specialize=["n", "base"])
def _shift_tail(
    a_ptr,
    b_ptr,
    n,
    base,
    BLOCK: tl.constexpr,
    STAGES: tl.constexpr,
    KILL: tl.constexpr,
):
    """Masked remainder of ``a << b``; ``tle.dsa.copy`` cannot express a mask."""
    idx = base + tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    keep = idx < n
    xa = tl.load(a_ptr + idx, mask=keep, other=0)
    xb = tl.load(b_ptr + idx, mask=keep, other=0)
    tl.store(a_ptr + idx, _shift_lanes(xa, xb, STAGES, KILL), mask=keep)


def __ilshift__(self, other):
    """``self <<= other``; mutates and returns ``self``."""
    logger.debug("GEMS __ILSHIFT__")
    if not torch.is_tensor(other):
        # Scalar shift amount: materialise a 0-dim tensor so one code path
        # serves every overload (never exercised by the tensor workloads).
        other = torch.tensor(other, dtype=self.dtype, device=self.device)

    target = self
    if not target.is_contiguous():
        target = target.contiguous()

    if other.shape != target.shape:
        shape = torch.broadcast_shapes(target.shape, other.shape)
        other = other.expand(shape).contiguous()

    n = target.numel()
    if n == 0:
        if target is not self:
            self.copy_(target)
        return self

    isize = target.element_size()
    block = _TILE_BYTES.get(isize, _TILE_BYTES_DEFAULT) // isize
    stages, kill = _SHIFT_PLAN.get(isize, _DEFAULT_PLAN)
    a_flat = target.reshape(-1)
    b_flat = other.reshape(-1)

    n_tile = n // block
    if n_tile > 0:
        nvec = _vector_core_count()
        # Keep every per-program element offset inside int32 range.
        max_tiles = (1 << 31) // block
        done = 0
        while done < n_tile:
            cnt = min(n_tile - done, max_tiles)
            grid = (min(cnt, nvec) if nvec else cnt,)
            off = done * block
            _shift_bulk[grid](
                a_flat[off:],
                b_flat[off:],
                cnt,
                BLOCK=block,
                NS=_NS,
                STAGES=stages,
                KILL=kill,
            )
            done += cnt

    base = n_tile * block
    if base < n:
        nblk = (n - base + block - 1) // block
        _shift_tail[(nblk,)](
            a_flat, b_flat, n, base, BLOCK=block, STAGES=stages, KILL=kill
        )

    if target is not self:
        self.copy_(target)
    return self
